export function topScores(scores: readonly number[], count: number): number[] {
  const sorted = (scores as number[]).sort((a, b) => b - a);
  return sorted.slice(0, count);
}

test_setup_files.behavior_test.js:
const assert = require('assert');
const { topScores } = require('./build/scores.js');
const scores = [10, 90, 40, 70, 20];
const snapshot = [...scores];
const top = topScores(scores, 3);
assert.deepStrictEqual(top, [90, 70, 40]);
assert.deepStrictEqual(scores, snapshot, "caller's array must NOT be mutated");
assert.deepStrictEqual(topScores([5], 3), [5]);
assert.deepStrictEqual(topScores([], 2), []);
console.log('PASS');

